function Replace-TaskLine([string]$text,[string]$pattern,[string]$replacement){
    $regex=[regex]::new($pattern,[Text.RegularExpressions.RegexOptions]::Multiline)
    if($regex.Matches($text).Count -ne 1){throw "Expected one continuity line: $pattern"}
    return $regex.Replace($text,[Text.RegularExpressions.MatchEvaluator]{param($match) $replacement})
}
